              "  @Input() points: Point[] = [];",
              "  private chart?: Chart;",
              "",
              "  ngOnChanges(changes: SimpleChanges) {",
              "    if (changes[\"points\"]) this.redraw();",
              "  }",
              "",
              "  ngOnDestroy() {",
              "    this.chart?.destroy();",
              "  }",
              "}"
