              "  mutationFn: (id: string) => likePost(id),",
              "  onMutate: async (id) => {",
              "    await queryClient.cancelQueries({ queryKey: [\"posts\", id] });",
              "    const prev = queryClient.getQueryData([\"posts\", id]);",
              "    queryClient.setQueryData([\"posts\", id], (old) => ({ ...old, liked: true }));",
              "    return { prev };",
              "  },",
              "  onError: (_e, id, ctx) => {",
