              "  for (let i = 0; i <= retries; i++) {",
              "    const signal = AbortSignal.timeout(timeout);",
              "    try {",
              "      const res = await fetch(url, { signal });",
              "      if (res.status >= 500 && i < retries) throw new Error(\"retryable\");",
              "      return res;",
              "    } catch {",
              "      if (i === retries) throw new Error(\"Недоступно\");",
