          h: "Пример кода",
          code: {
            lang: "javascript",
            title: "circuit-breaker.js",
            lines: [
              "let failures = 0; let openedAt = 0;",
              "async function guardedFetch(url, options) {",
              "  if (failures >= 5 && Date.now() - openedAt < 15000) throw new Error(\"SERVICE_DOWN\");",
              "  try {",
              "    const res = await fetch(url, options);",
              "    if (!res.ok) throw new Error();",
              "    failures = 0;",
              "    return res;",
              "  } catch (e) {",
              "    if (failures === 0) openedAt = Date.now();",
              "    failures += 1;",
              "    throw e;",
              "  }",
              "}"
            ]
          }
